#include "../include/arena.h"
#include "../include/lexer.h"
#include "../include/parser.h"
#include "../include/codegen.h"
#include "../include/ast.h"
#include <stdio.h>
#include <stdlib.h>


// function to read the entire contents of a file into a string
// we need this function to read code from a file and pass it to the lexer for tokenization
// after we pass the code to the lexer, we will print out the tokens generated by the lexer to verify that it is working correctly
static char* read_entire_file(const char *path){

    // open the file in binary mode
    FILE *file = fopen(path, "rb");


    // if there is no file , output an error message and exit the program 
    // with status code EXIT_FAILUREj
    if(!file){
        fprintf(stderr, "Error: Could not open file %s\n", path);
        exit(EXIT_FAILURE);
    }

    // move the file pointer to the end of the file to determine its length of the file
    fseek(file, 0, SEEK_END);

    // get the length of the file by using ftell to get the current position of the file pointer
    long length = ftell(file);

    // move the file pointer back to the beginning of the file so we can read its contents
    fseek(file, 0, SEEK_SET);

    // based on the length of file, allocate the memory for the buffer to hold the contents of the file
    // this buffer will be used to store the contents of the file so that we can pass it to the lexer for tokenization
    char *buf = (char *)malloc(length + 1);

    // if there is no buffer being allocated, output an error message 
    // and exit the program with status code EXIT_FAILURE
    if(!buf){
        perror("Error: Could not allocate memory for file buffer");
        fclose(file);
        return NULL;
    }

    // read the contents of the file into the buffer
    fread(buf, 1, length, file);

    // null terminate the buffer to make it a valid C string
    buf[length] = '\0'; // Null-terminate the buffer

    // close the file after reading its contents
    fclose(file);

    // return the buffer containing the contents of the file
    // buffer is a dynamic memory allocator , in general , it is used to store the content of the file in memory s
    // so that it can be processed by another function or module
    return buf;



}



// function to test the lexer by reading a source file , tokenize it , and print out the tokens generated by the lexer
// the tokens generated are required as it will be used by the parser to generate an abstract syntax tree (AST) for the source code
// the AST will be used by the code generator to generate machine code for the source code
int main(int argc , char **argv){

    // check if the user has provided a source file as a command line argument
    // if not , output an error message and exit the program with status code EXIT_FAILURE
    if(argc < 2){
        
        fprintf(stderr, "Usage: %s <source_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_path = argv[2];
    const char *output_path = argv[4];

    // read the entire contents of the source file into a string
    // this string will be passed to the lexer for tokenization
    char *source = read_entire_file(input_path);

    // if the source file could not be read , output an error message and exit the program with status code EXIT_FAILURE
    if(!source){
        return EXIT_FAILURE;
    }

    // log for debugging purposes, print the source code to the console
    printf("Source code:\n%s\n", source);
    printf("Tokenizing source code...\n");

   
    // init the arena for memory allocation by defaulting the value of 4mb memory
    Arena arena = arena_create(4 * 1024 * 1024);

    // init the lexer instance to parse the lexer from the source code
    Lexer lexer;
    lexer_init(&lexer , source);

    // init the parser instance to start parsing the syntax
    Parser parser;
    parser_init(&parser , &lexer , &arena);

    printf("Parsing %s...\n", argv[1]); 
    ASTNode *root = parser_parse_translation_unit(&parser);


    FILE *out = fopen(output_path , "w");
        if(!out){
            perror("Error creating output file");
            free(source);
            arena_free(&arena);
            return EXIT_FAILURE;
        }

    codegen_go(root, out);
    fclose(out);
    


    printf("\n--- Abstract Syntax Tree ---\n");
    ast_print(root, 0);
    printf("----------------------------\n");

    free(source);
    arena_free(&arena);

    printf("Successfully transpiled %s -> %s\n" , input_path , output_path);
    return EXIT_SUCCESS;
}